args:
set -eu
if [ -n "${NOTEBOOK_APP:-}" ]; then app=$NOTEBOOK_APP
elif [ -d "$HOME/Applications/Notebook.app" ]; then app="$HOME/Applications/Notebook.app"
elif [ -d /Applications/Notebook.app ]; then app=/Applications/Notebook.app
else printf '%s\n' 'Install Notebook for Mac before connecting its Codex plugin.' >&2; exit 1
fi
node="$app/Contents/Resources/CodexRuntime/node"
server="$app/Contents/Resources/NotebookTools/dist/index.mjs"
[ -x "$node" ] && [ -r "$server" ] || { printf '%s\n' 'Notebook bundled runtime is unavailable.' >&2; exit 1; }
NOTEBOOK_SOCKET=${NOTEBOOK_SOCKET:-/tmp/notebook-$(id -u)/bridge.sock}
export NOTEBOOK_SOCKET
probe='
const fs = require("node:fs"), net = require("node:net"), path = require("node:path"), crypto = require("node:crypto");
const endpoint = process.argv[1], deadline = Date.now() + Number(process.argv[2] || 0);
function ready() { return new Promise(resolve => {
  let socket, data = Buffer.alloc(0), settled = false;
  const id = crypto.randomUUID();
  const done = ok => { if (settled) return; settled = true; clearTimeout(timer); socket?.destroy(); resolve(ok); };
  const timer = setTimeout(() => done(false), deadline > Date.now() ? Math.min(300, deadline - Date.now()) : 300);
  try {
    const directory = fs.lstatSync(path.dirname(endpoint)), entry = fs.lstatSync(endpoint), uid = process.getuid();
    if (!directory.isDirectory() || directory.uid !== uid || (directory.mode & 511) !== 448 || !entry.isSocket() || entry.uid !== uid || (entry.mode & 511) !== 384) return done(false);
    socket = net.createConnection(endpoint);
    socket.once("connect", () => {
      const payload = Buffer.from(JSON.stringify({version:1,id,request:{command:"read",queries:[{kind:"workspaceHeader"}]}}));
      const size = Buffer.alloc(4); size.writeUInt32BE(payload.length); socket.end(Buffer.concat([size,payload]));
    });
    socket.on("data", chunk => {
      data = Buffer.concat([data,chunk]);
      if (data.length < 4) return;
      const size = data.readUInt32BE(0);
      if (!size || size > 1048576 || data.length > size + 4) return done(false);
      if (data.length !== size + 4) return;
      try { const reply = JSON.parse(data.subarray(4)); done(reply.version === 1 && String(reply.id).toLowerCase() === id && !reply.error && "result" in reply); }
      catch { done(false); }
    });
    socket.once("error", () => done(false)); socket.once("end", () => done(false));
  } catch { done(false); }
}); }
(async () => { do { if (await ready()) return; const remaining = deadline - Date.now(); if (remaining <= 0) process.exit(1); await new Promise(resolve => setTimeout(resolve, Math.min(200, remaining))); if (Date.now() >= deadline) process.exit(1); } while (true); })();
'
if ! "$node" -e "$probe" "$NOTEBOOK_SOCKET" 0; then
  /usr/bin/open -gj "$app" --args --background
  "$node" -e "$probe" "$NOTEBOOK_SOCKET" 6000 || { printf '%s\n' 'Notebook has not admitted its workspace. Open Notebook to inspect startup.' >&2; exit 1; }
fi
exec "$node" "$server"
